{"summary":"Create bridge/transform-host.js","command":"create","file_text":"/**
 * Bridge transform host for jscodeshift Rust runner.
 * Executes JavaScript/TypeScript transforms with full ast-types, recast, babel, and parser support.
 */

'use strict';

const readline = require('readline');
const fs = require('fs');
const path = require('path');
const writeFileAtomic = require('write-file-atomic');
const { DEFAULT_EXTENSIONS } = require('@babel/core');

const jscodeshift = require('../src_js/core');
const getParser = require('../src_js/getParser');

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

let transform;
let parserFromTransform;

const transformPath = process.argv[2];
const babelMode = process.argv[3];

function setup(tr, babel) {
  if (babel === 'babel') {
    const presets = [];
    if (presetEnv) {
      presets.push([
        presetEnv.default,
        { targets: { node: true } },
      ]);
    }
    presets.push(
      /\.tsx?$/.test(tr)
        ? require('@babel/preset-typescript').default
        : require('@babel/preset-flow').default
    );

    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const mod = require(path.isAbsolute(tr) ? tr : path.resolve(process.cwd(), tr));
  transform = typeof mod.default === 'function' ? mod.default : mod;
  if (mod.parser) {
    parserFromTransform = typeof mod.parser === 'string'
      ? getParser(mod.parser)
      : mod.parser;
  }
}

function send(msg) {
  process.stdout.write(JSON.stringify(msg) + '\n');
}

function trimStackTrace(trace) {
  if (!trace) {
    return '';
  }
  const lines = trace.split('\n');
  const result = [];
  lines.every(function(line) {
    if (line.indexOf(__filename) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

function prepareJscodeshift(options) {
  const parser = parserFromTransform ||
    getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

async function processFile(file, options, statsCounter) {
  let source;
  try {
    source = fs.readFileSync(file, 'utf8');
  } catch (err) {
    send({ action: 'status', status: 'error', msg: `${file} File error: ${err}` });
    return;
  }

  try {
    const j = prepareJscodeshift(options);
    const out = await transform(
      {
        path: file,
        source: source,
      },
      {
        j: j,
        jscodeshift: j,
        stats: options.dry
          ? (name, quantity = 1) => {
              statsCounter[name] = (statsCounter[name] || 0) + quantity;
            }
          : () => {},
        report: (msg) => {
          send({ action: 'report', file: file, msg: msg });
        },
      },
      options
    );

    // Send accumulated stats
    for (const name of Object.keys(statsCounter)) {
      if (statsCounter[name]) {
        send({ action: 'update', name: name, quantity: statsCounter[name] });
        statsCounter[name] = 0;
      }
    }

    if (!out || out === source) {
      send({ action: 'status', status: out ? 'nochange' : 'skip', msg: file });
      return;
    }

    if (options.print) {
      send({ action: 'print', text: out });
    }

    if (!options.dry) {
      await new Promise((resolve) => {
        writeFileAtomic(file, out, (err) => {
          if (err) {
            send({ action: 'status', status: 'error', msg: `${file} File writer error: ${err}` });
          } else {
            send({ action: 'status', status: 'ok', msg: file });
          }
          resolve();
        });
      });
    } else {
      send({ action: 'status', status: 'ok', msg: file });
    }
  } catch (err) {
    send({
      action: 'status',
      status: 'error',
      msg: `${file} Transformation error (${err.message.replace(/\n/g, ' ')})\n${trimStackTrace(err.stack)}`,
    });
  }
}

async function runChunk(files, options) {
  if (!files || files.length === 0) {
    process.exit(0);
    return;
  }
  const statsCounter = {};
  for (const file of files) {
    await processFile(file, options, statsCounter);
  }
  send({ action: 'free' });
}

if (transformPath) {
  setup(transformPath, babelMode);
}

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false,
});

rl.on('line', async (line) => {
  if (!line.trim()) return;
  try {
    const data = JSON.parse(line);
    if (data.action === 'exit' || (data.files && data.files.length === 0)) {
      process.exit(0);
    }
    await runChunk(data.files || [], data.options || {});
  } catch (err) {
    console.error('Bridge error:', err);
  }
});
