use std::collections::BTreeMap;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Options {
    pub transform: String,
    pub cpus: Option<usize>,
    pub verbose: usize,
    pub dry: bool,
    pub print: bool,
    pub babel: bool,
    pub extensions: String,
    pub ignore_pattern: Vec<String>,
    pub ignore_config: Vec<String>,
    pub gitignore: bool,
    pub run_in_band: bool,
    pub silent: bool,
    pub parser: String,
    pub parser_config: Option<String>,
    pub fail_on_error: bool,
    pub stdin: bool,
    pub positional_arguments: Vec<String>,
    pub extra: BTreeMap<String, serde_json::Value>,
}

impl Default for Options {
    fn default() -> Self {
        Self {
            transform: "./transform.js".to_string(),
            cpus: None,
            verbose: 0,
            dry: false,
            print: false,
            babel: true,
            extensions: "cjs,es,es6,js,jsx,mjs,ts,tsx".to_string(),
            ignore_pattern: Vec::new(),
            ignore_config: Vec::new(),
            gitignore: false,
            run_in_band: false,
            silent: false,
            parser: "babel".to_string(),
            parser_config: None,
            fail_on_error: false,
            stdin: false,
            positional_arguments: Vec::new(),
            extra: BTreeMap::new(),
        }
    }
}

pub enum ParseOutcome {
    Success(Options),
    Help(String),
    Version(String),
}

pub struct ArgError {
    pub exit_code: i32,
    pub message: String,
}

