fn format_option(opt: &OptionDef) -> String {
    let mut text = String::from("  ");
    if let Some(abbr) = opt.abbr {
        text.push('-');
        text.push(abbr);
        text.push_str(", ");
    } else {
        text.push_str("    ");
    }

    text.push_str("--");
    if opt.flag {
        text.push_str("(no-)");
    }
    text.push_str(opt.full);

    if let Some(choices) = opt.choices {
        text.push('=');
        text.push_str(&choices.join("|"));
    } else if let Some(metavar) = opt.metavar {
        text.push('=');
        text.push_str(metavar);
    }

    if opt.list {
        text.push_str(" ...");
    }

    if opt.default_help.is_some() || opt.default_val.is_some() || !opt.help.is_empty() {
        text.push_str("  ");
        if text.len() < 32 {
            text.push_str(&" ".repeat(32 - text.len()));
        }
        let text_length = text.len();
        if !opt.help.is_empty() {
            text.push_str(opt.help);
        }
        if let Some(def) = opt.default_help.or(opt.default_val) {
            if !opt.help.is_empty() {
                text.push('\n');
            }
            text.push_str(&" ".repeat(text_length));
            text.push_str(&format!("(default: {})", def));
        }
    }

    text
}

pub fn get_help_text() -> String {
    let mut sorted_opts: Vec<&OptionDef> = OPTIONS_DEFS.iter().collect();
    sorted_opts.sort_by_key(|o| o.display_index);

    let opts_formatted: Vec<String> = sorted_opts.into_iter().map(format_option).collect();

    let text = format!(
        "Usage: jscodeshift [OPTION]... PATH...\n  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  or:  jscodeshift [OPTION]... -t URL PATH...\n  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\nApply transform logic in TRANSFORM_PATH (recursively) to every PATH.\nIf --stdin is set, each line of the standard input is used as a path.\n\nOptions:\n\"...\" behind an option means that it can be supplied multiple times.\nAll options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n{}\n",
        opts_formatted.join("\n")
    );
    text
}

pub fn get_version_text() -> String {
    "jscodeshift: 17.4.0\n - babel: 7.29.6\n - babylon: 7.29.7\n - flow: 0.237.2\n - recast: 0.23.11\n".to_string()
}

fn parse_json_value(val: &str) -> serde_json::Value {
    if let Ok(v) = serde_json::from_str::<serde_json::Value>(val) {
        v
    } else {
        serde_json::Value::String(val.to_string())
    }
}

pub fn parse(args: &[String]) -> Result<ParseOutcome, ArgError> {
    let mut options = Options::default();
    let mut positional_arguments = Vec::new();

    // Track missing values
    let mut missing_value_option: Option<&'static str> = None;

    // Track list options
    let mut ignore_pattern = Vec::new();
    let mut ignore_config = Vec::new();
    let mut custom_lists: BTreeMap<String, Vec<serde_json::Value>> = BTreeMap::new();

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if arg.starts_with('-') && arg != "-" {
            let (option_name, explicit_value) = if let Some(idx) = arg.find('=') {
                (&arg[..idx], Some(&arg[idx + 1..]))
            } else {
                (arg.as_str(), None)
            };

            // Match known options
            let mut matched_def: Option<&'static OptionDef> = None;
            for def in OPTIONS_DEFS {
                let full_long = format!("--{}", def.full);
                let no_long = format!("--no-{}", def.full);
                let abbr_short = def.abbr.map(|c| format!("-{}", c));

                if option_name == full_long
                    || (def.flag && option_name == no_long)
                    || abbr_short.as_deref() == Some(option_name)
                {
                    matched_def = Some(def);
                    break;
                }
            }

            if let Some(def) = matched_def {
                if def.key == "help" {
                    return Ok(ParseOutcome::Help(get_help_text()));
                }
                if def.key == "version" {
                    return Ok(ParseOutcome::Version(get_version_text()));
                }

                if def.flag {
                    let val = if option_name.starts_with("--no-") {
                        false
                    } else if let Some(ev) = explicit_value {
                        ev == "1"
                    } else {
                        true
                    };

                    match def.key {
                        "babel" => options.babel = val,
                        "dry" => options.dry = val,
                        "print" => options.print = val,
                        "failOnError" => options.fail_on_error = val,
                        "gitignore" => options.gitignore = val,
                        "runInBand" => options.run_in_band = val,
                        "silent" => options.silent = val,
                        "stdin" => options.stdin = val,
                        _ => {}
                    }
                } else {
                    let val = if let Some(ev) = explicit_value {
                        Some(ev.to_string())
                    } else if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                        i += 1;
                        Some(args[i].clone())
                    } else {
                        None
                    };

                    if let Some(v) = val {
                        match def.key {
                            "transform" => options.transform = v,
                            "cpus" => {
                                if let Ok(n) = v.parse::<usize>() {
                                    options.cpus = Some(n);
                                }
                            }
                            "verbose" => {
                                if let Some(choices) = def.choices {
                                    if !choices.contains(&v.as_str()) {
                                        let msg = format!("Error: --verbose must be one of the values {}", choices.join(","));
                                        return Err(ArgError {
                                            exit_code: 1,
                                            message: format!("{}\n\n---\n\n{}", msg, get_help_text()),
                                        });
                                    }
                                }
                                if let Ok(n) = v.parse::<usize>() {
                                    options.verbose = n;
                                }
                            }
                            "extensions" => options.extensions = v,
                            "ignorePattern" => ignore_pattern.push(v),
                            "ignoreConfig" => ignore_config.push(v),
                            "parser" => {
                                if let Some(choices) = def.choices {
                                    if !choices.contains(&v.as_str()) {
                                        let msg = format!("Error: --parser must be one of the values {}", choices.join(","));
                                        return Err(ArgError {
                                            exit_code: 1,
                                            message: format!("{}\n\n---\n\n{}", msg, get_help_text()),
                                        });
                                    }
                                }
                                options.parser = v;
                            }
                            "parserConfig" => options.parser_config = Some(v),
                            _ => {}
                        }
                    } else {
                        missing_value_option = Some(def.full);
                    }
                }
            } else {
                // Unknown option
                let raw_name = option_name.trim_start_matches('-');
                let real_name = raw_name.strip_prefix("no-").unwrap_or(raw_name).to_string();

                let is_flag = explicit_value.is_none()
                    && (i + 1 == args.len() || args[i + 1].starts_with('-'));

                if is_flag {
                    let val = !option_name.starts_with("--no-");
                    options.extra.insert(real_name, serde_json::Value::Bool(val));
                } else {
                    let val_str = if let Some(ev) = explicit_value {
                        Some(ev.to_string())
                    } else if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                        i += 1;
                        Some(args[i].clone())
                    } else {
                        None
                    };

                    if let Some(vs) = val_str {
                        let parsed = parse_json_value(&vs);
                        if let Some(list) = custom_lists.get_mut(&real_name) {
                            list.push(parsed);
                        } else if let Some(existing) = options.extra.get(&real_name) {
                            let mut list = match existing {
                                serde_json::Value::Bool(_) => Vec::new(),
                                other => vec![other.clone()],
                            };
                            list.push(parsed);
                            custom_lists.insert(real_name.clone(), list);
                        } else {
                            options.extra.insert(real_name, parsed);
                        }
                    }
                }
            }
        } else {
            positional_arguments.push(arg.clone());
        }
        i += 1;
    }

    if let Some(missing_name) = missing_value_option {
        let msg = format!("Missing value: --{} requires a value", missing_name);
        return Err(ArgError {
            exit_code: 1,
            message: format!("{}\n\n---\n\n{}", msg, get_help_text()),
        });
    }

    for (k, v) in custom_lists {
        options.extra.insert(k, serde_json::Value::Array(v));
    }

    options.ignore_pattern = ignore_pattern;
    options.ignore_config = ignore_config;
    options.positional_arguments = positional_arguments;

    if options.positional_arguments.is_empty() && !options.stdin {
        return Err(ArgError {
            exit_code: 1,
            message: format!(
                "Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}",
                get_help_text()
            ),
        });
    }

    Ok(ParseOutcome::Success(options))
}
