{"file_text":"use globset::{Glob, GlobSet, GlobSetBuilder};
use std::fs;
use std::path::Path;

#[derive(Debug, Clone, Default)]
pub struct IgnoreFiles {
    patterns: Vec<String>,
    glob_set: Option<GlobSet>,
}

impl IgnoreFiles {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add_ignore_pattern(&mut self, val: &str) {
        let trimmed = val.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            return;
        }

        if !trimmed.contains('/') {
            self.patterns.push(format!("**/{}", trimmed));
        }

        if trimmed.ends_with('/') {
            self.patterns.push(format!("**/{}**", trimmed));
            self.patterns.push(format!("{}**", trimmed));
        }

        self.patterns.push(trimmed.to_string());
        self.glob_set = None;
    }

    pub fn add_ignore_from_input(&mut self, patterns: &[String]) {
        for p in patterns {
            self.add_ignore_pattern(p);
        }
    }

    pub fn add_ignore_from_file(&mut self, files: &[String]) {
        for file in files {
            let path = Path::new(file);
            if path.exists() && path.is_file() {
                if let Ok(content) = fs::read_to_string(path) {
                    for line in content.lines() {
                        self.add_ignore_pattern(line);
                    }
                }
            }
        }
    }

    pub fn build(&mut self) {
        let mut builder = GlobSetBuilder::new();
        for pattern in &self.patterns {
            if let Ok(glob) = Glob::new(pattern) {
                builder.add(glob);
            }
        }
        self.glob_set = builder.build().ok();
    }

    pub fn should_ignore(&mut self, path: &str) -> bool {
        if self.patterns.is_empty() {
            return false;
        }

        if self.glob_set.is_none() {
            self.build();
        }

        let glob_set = match &self.glob_set {
            Some(gs) => gs,
            None => return false,
        };

        // Normalize path by stripping leading ../ or ./
        let normalized = normalize_path(path);

        glob_set.is_match(path) || glob_set.is_match(&normalized)
    }
}

fn normalize_path(p: &str) -> String {
    let mut s = p;
    loop {
        if s.starts_with("./") {
            s = &s[2..];
        } else if s.starts_with(".\\") {
            s = &s[2..];
        } else if s.starts_with("../") {
            s = &s[3..];
        } else if s.starts_with("..\\") {
            s = &s[3..];
        } else {
            break;
        }
    }
    s.to_string()
}
