{"path":"/workspace/codebase/src/worker.rs","command":"create","summary":"Create src/worker.rs","file_text":"use serde::{Deserialize, Serialize};
use std::io::{self, BufRead, BufReader, BufWriter, Write};
use std::path::Path;
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};

#[derive(Debug, Serialize, Deserialize)]
pub struct WorkerInput {
    pub files: Vec<String>,
    pub options: serde_json::Value,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "action")]
pub enum WorkerMessage {
    #[serde(rename = "status")]
    Status { status: String, msg: String },
    #[serde(rename = "report")]
    Report { file: String, msg: String },
    #[serde(rename = "update")]
    Update { name: String, quantity: usize },
    #[serde(rename = "print")]
    Print { text: String },
    #[serde(rename = "free")]
    Free,
}

pub struct Worker {
    _child: Child,
    writer: BufWriter<ChildStdin>,
    reader: io::Lines<BufReader<ChildStdout>>,
}

impl Worker {
    pub fn spawn(
        transform_file: &str,
        babel: bool,
        bridge_path: &Path,
    ) -> io::Result<Self> {
        let babel_flag = if babel { "babel" } else { "no-babel" };
        let mut child = Command::new("node")
            .arg(bridge_path)
            .arg(transform_file)
            .arg(babel_flag)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .spawn()?;

        let stdin = child.stdin.take().ok_or_else(|| {
            io::Error::new(io::ErrorKind::Other, "Failed to open worker stdin")
        })?;
        let stdout = child.stdout.take().ok_or_else(|| {
            io::Error::new(io::ErrorKind::Other, "Failed to open worker stdout")
        })?;

        let writer = BufWriter::new(stdin);
        let reader = BufReader::new(stdout).lines();

        Ok(Worker {
            _child: child,
            writer,
            reader,
        })
    }

    pub fn send_chunk(&mut self, files: Vec<String>, options: &serde_json::Value) -> io::Result<()> {
        let payload = WorkerInput {
            files,
            options: options.clone(),
        };
        let line = serde_json::to_string(&payload)?;
        self.writer.write_all(line.as_bytes())?;
        self.writer.write_all(b"\n")?;
        self.writer.flush()?;
        Ok(())
    }

    pub fn next_message(&mut self) -> Option<WorkerMessage> {
        for line_res in &mut self.reader {
            if let Ok(line) = line_res {
                let trimmed = line.trim();
                if trimmed.is_empty() {
                    continue;
                }
                if let Ok(msg) = serde_json::from_str::<WorkerMessage>(trimmed) {
                    return Some(msg);
                }
            }
        }
        None
    }

    pub fn close(&mut self) {
        let _ = self.writer.write_all(b"{\"action\":\"exit\",\"files\":[]}\n");
        let _ = self.writer.flush();
    }
}
"}

{"summary":"Create src/runner.rs","command":"create","file_text":"use crate::args::Options;
use crate::ignore::IgnoreFiles;
use crate::worker::{Worker, WorkerMessage};
use std::collections::BTreeMap;
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::Instant;
use tempfile::NamedTempFile;

#[derive(Debug, Default)]
pub struct FileCounters {
    pub error: usize,
    pub ok: usize,
    pub nochange: usize,
    pub skip: usize,
}

pub fn run(options: &Options) -> Result<i32, Box<dyn std::error::Error>> {
    let start_time = Instant::now();

    // Setup ignore patterns
    let mut ignores = IgnoreFiles::new();
    if options.gitignore {
        ignores.add_ignore_from_file(&[".gitignore".to_string()]);
    }
    ignores.add_ignore_from_file(&options.ignore_config);
    ignores.add_ignore_from_input(&options.ignore_pattern);
    ignores.build();

    // Prepare extension list
    let allowed_extensions: Vec<String> = options
        .extensions
        .split(',')
        .map(|s| {
            let s = s.trim();
            if s.starts_with('.') {
                s.to_string()
            } else {
                format!(".{}", s)
            }
        })
        .collect();

    // Resolve transform file (handle remote URL if necessary)
    let _temp_transform_holder: Option<NamedTempFile>;
    let transform_path = if options.transform.starts_with("http://")
        || options.transform.starts_with("https://")
    {
        let ext = Path::new(&options.transform)
            .extension()
            .and_then(|e| e.to_str())
            .unwrap_or("js");
        let temp_file = tempfile::Builder::new()
            .suffix(&format!(".{}", ext))
            .tempfile()?;
        let temp_path = temp_file.path().to_string_lossy().to_string();

        let status = Command::new("curl")
            .arg("-sSL")
            .arg(&options.transform)
            .arg("-o")
            .arg(&temp_path)
            .status();

        match status {
            Ok(s) if s.success() => {
                _temp_transform_holder = Some(temp_file);
                temp_path
            }
            _ => {
                eprint!(
                    "\x1b[41m\x1b[37mERROR\x1b[39m\x1b[49m Transform file {} does not exist \n",
                    options.transform
                );
                return Ok(0);
            }
        }
    } else {
        let p = Path::new(&options.transform);
        if !p.exists() {
            eprint!(
                "\x1b[41m\x1b[37mERROR\x1b[39m\x1b[49m Transform file {} does not exist \n",
                options.transform
            );
            return Ok(0);
        }
        let abs = if p.is_absolute() {
            p.to_path_buf()
        } else {
            std::env::current_dir()?.join(p)
        };
        abs.to_string_lossy().to_string()
    };

    // Discover files
    let mut files = Vec::new();
    for root_path in &options.positional_arguments {
        let p = Path::new(root_path);
        if !p.exists() {
            eprint!("Skipping path {} which does not exist. \n", root_path);
            continue;
        }

        if p.is_dir() {
            let mut dir_files = Vec::new();
            collect_dir_files(p, &mut dir_files, &mut ignores);
            for f in dir_files {
                if has_allowed_extension(&f, &allowed_extensions) {
                    files.push(f);
                }
            }
        } else {
            let path_str = root_path.clone();
            if !has_allowed_extension(&path_str, &allowed_extensions)
                || ignores.should_ignore(&path_str)
            {
                continue;
            }
            files.push(path_str);
        }
    }

    if files.is_empty() {
        print!("No files selected, nothing to do. \n");
        return Ok(0);
    }

    let num_files = files.len();
    let available_cpus = num_cpus::get().saturating_sub(1).max(1);
    let cpus = options.cpus.unwrap_or(available_cpus).min(available_cpus);
    let processes = if options.run_in_band {
        1
    } else {
        num_files.min(cpus)
    };

    let chunk_size = if processes > 1 {
        ((num_files as f64 / processes as f64).ceil() as usize)
            .min(50)
            .max(1)
    } else {
        num_files
    };

    if !options.silent {
        print!("Processing {} files... \n", num_files);
        if !options.run_in_band {
            print!("Spawning {} workers...\n", processes);
        }
        if options.dry {
            print!("\x1b[32mRunning in dry mode, no files will be written! \n\x1b[39m");
        }
    }

    // Locate bridge
    let bridge_path = find_bridge_path();

    // Serialize options for worker
    let mut options_val = serde_json::to_value(options)?;
    if let Some(obj) = options_val.as_object_mut() {
        for (k, v) in &options.extra {
            obj.insert(k.clone(), v.clone());
        }
    }

    let mut file_counters = FileCounters::default();
    let mut stats_counter: BTreeMap<String, usize> = BTreeMap::new();

    // Chunk files and run workers
    let chunks: Vec<Vec<String>> = files.chunks(chunk_size).map(|c| c.to_vec()).collect();

    if options.run_in_band || processes <= 1 {
        let mut worker = Worker::spawn(&transform_path, options.babel, &bridge_path)?;
        for chunk in chunks {
            worker.send_chunk(chunk, &options_val)?;
            while let Some(msg) = worker.next_message() {
                match msg {
                    WorkerMessage::Status { status, msg } => {
                        handle_status(&status, &msg, options.verbose, &mut file_counters);
                    }
                    WorkerMessage::Report { file, msg } => {
                        print!("\x1b[44m\x1b[37m REP \x1b[39m\x1b[49m{} {}\n", file, msg);
                    }
                    WorkerMessage::Update { name, quantity } => {
                        *stats_counter.entry(name).or_insert(0) += quantity;
                    }
                    WorkerMessage::Print { text } => {
                        println!("{}", text);
                    }
                    WorkerMessage::Free => {
                        break;
                    }
                }
            }
        }
        worker.close();
    } else {
        // Multi-worker pool
        let mut workers: Vec<Worker> = Vec::with_capacity(processes);
        for _ in 0..processes {
            workers.push(Worker::spawn(&transform_path, options.babel, &bridge_path)?);
        }

        let mut chunk_idx = 0;
        let num_chunks = chunks.len();

        // Send initial chunk to each worker
        for worker in workers.iter_mut() {
            if chunk_idx < num_chunks {
                if !options.silent {
                    print!("Sending {} files to free worker...\n", chunks[chunk_idx].len());
                }
                worker.send_chunk(chunks[chunk_idx].clone(), &options_val)?;
                chunk_idx += 1;
            }
        }

        // Process remaining chunks as workers free up
        for worker in workers.iter_mut() {
            loop {
                let mut is_free = false;
                while let Some(msg) = worker.next_message() {
                    match msg {
                        WorkerMessage::Status { status, msg } => {
                            handle_status(&status, &msg, options.verbose, &mut file_counters);
                        }
                        WorkerMessage::Report { file, msg } => {
                            print!("\x1b[44m\x1b[37m REP \x1b[39m\x1b[49m{} {}\n", file, msg);
                        }
                        WorkerMessage::Update { name, quantity } => {
                            *stats_counter.entry(name).or_insert(0) += quantity;
                        }
                        WorkerMessage::Print { text } => {
                            println!("{}", text);
                        }
                        WorkerMessage::Free => {
                            is_free = true;
                            break;
                        }
                    }
                }

                if is_free {
                    if chunk_idx < num_chunks {
                        if !options.silent {
                            print!("Sending {} files to free worker...\n", chunks[chunk_idx].len());
                        }
                        worker.send_chunk(chunks[chunk_idx].clone(), &options_val)?;
                        chunk_idx += 1;
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }
            worker.close();
        }
    }

    if !options.silent {
        print!("All done. \n");
        print!("Results: \n");
        print!("\x1b[31m{} errors\n\x1b[39m", file_counters.error);
        print!("\x1b[33m{} unmodified\n\x1b[39m", file_counters.nochange);
        print!("\x1b[33m{} skipped\n\x1b[39m", file_counters.skip);
        print!("\x1b[32m{} ok\n\x1b[39m", file_counters.ok);

        if !stats_counter.is_empty() {
            print!("\x1b[34mStats: \n\x1b[39m");
            for (name, qty) in &stats_counter {
                print!("{}: {}\n", name, qty);
            }
        }

        let elapsed = start_time.elapsed().as_secs_f64();
        print!("Time elapsed: {:.3}seconds \n", elapsed);
    }

    if options.fail_on_error && file_counters.error > 0 {
        Ok(1)
    } else {
        Ok(0)
    }
}

fn handle_status(status: &str, msg: &str, verbose: usize, counters: &mut FileCounters) {
    let line = if msg.ends_with('\n') {
        msg.to_string()
    } else {
        format!("{}\n", msg)
    };

    match status {
        "ok" => {
            counters.ok += 1;
            if verbose >= 2 {
                print!("\x1b[42m\x1b[37m OKK \x1b[39m\x1b[49m{}", line);
            }
        }
        "nochange" => {
            counters.nochange += 1;
            if verbose >= 1 {
                print!("\x1b[43m\x1b[37m NOC \x1b[39m\x1b[49m{}", line);
            }
        }
        "skip" => {
            counters.skip += 1;
            if verbose >= 1 {
                print!("\x1b[43m\x1b[37m SKIP \x1b[39m\x1b[49m{}", line);
            }
        }
        "error" => {
            counters.error += 1;
            if verbose >= 0 {
                eprint!("\x1b[41m\x1b[37m ERR \x1b[39m\x1b[49m{}", line);
            }
        }
        _ => {}
    }
}

fn collect_dir_files(dir: &Path, acc: &mut Vec<String>, ignores: &mut IgnoreFiles) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    let mut sorted_entries: Vec<_> = entries.filter_map(|e| e.ok()).collect();
    sorted_entries.sort_by_key(|e| e.file_name());

    for entry in sorted_entries {
        let p = entry.path();
        let path_str = p.to_string_lossy().to_string();

        if !p.exists() {
            let _ = io::stdout().write_all(format!("Skipping path \"{}\" which does not exist.\n", path_str).as_bytes());
            continue;
        }

        if ignores.should_ignore(&path_str) {
            continue;
        }

        if p.is_dir() {
            collect_dir_files(&p, acc, ignores);
        } else {
            acc.push(path_str);
        }
    }
}

fn has_allowed_extension(file: &str, allowed_exts: &[String]) -> bool {
    let p = Path::new(file);
    if let Some(ext) = p.extension().and_then(|e| e.to_str()) {
        let dot_ext = format!(".{}", ext);
        allowed_exts.contains(&dot_ext)
    } else {
        false
    }
}

fn find_bridge_path() -> PathBuf {
    let direct = Path::new("bridge/transform-host.js");
    if direct.exists() {
        return direct.to_path_buf();
    }

    if let Ok(exe) = std::env::current_exe() {
        if let Some(parent) = exe.parent() {
            // Check ../../bridge/transform-host.js (from target/release/)
            let candidate = parent.join("../../bridge/transform-host.js");
            if candidate.exists() {
                return candidate;
            }
            let candidate2 = parent.join("../bridge/transform-host.js");
            if candidate2.exists() {
                return candidate2;
            }
        }
    }

    PathBuf::from("bridge/transform-host.js")
}
