{"summary":"Create src/collection.rs","path":"/workspace/codebase/src/collection.rs","file_text":"use serde::{Deserialize, Serialize};
use std::collections::HashMap;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct AstNode {
    pub node_type: String,
    pub attributes: HashMap<String, serde_json::Value>,
    pub children: Vec<AstNode>,
}

impl AstNode {
    pub fn new(node_type: impl Into<String>) -> Self {
        Self {
            node_type: node_type.into(),
            attributes: HashMap::new(),
            children: Vec::new(),
        }
    }

    pub fn with_attr(mut self, key: impl Into<String>, val: serde_json::Value) -> Self {
        self.attributes.insert(key.into(), val);
        self
    }

    pub fn with_child(mut self, child: AstNode) -> Self {
        self.children.push(child);
        self
    }
}

#[derive(Debug, Clone, Default)]
pub struct Collection {
    pub nodes: Vec<AstNode>,
}

impl Collection {
    pub fn new(nodes: Vec<AstNode>) -> Self {
        Self { nodes }
    }

    pub fn from_node(node: AstNode) -> Self {
        Self { nodes: vec![node] }
    }

    pub fn size(&self) -> usize {
        self.nodes.len()
    }

    pub fn is_empty(&self) -> bool {
        self.nodes.is_empty()
    }

    pub fn get(&self, index: usize) -> Option<&AstNode> {
        self.nodes.get(index)
    }

    pub fn get_mut(&mut self, index: usize) -> Option<&mut AstNode> {
        self.nodes.get_mut(index)
    }

    pub fn nodes(&self) -> &[AstNode] {
        &self.nodes
    }

    pub fn find(&self, target_type: &str) -> Self {
        let mut matched = Vec::new();
        for node in &self.nodes {
            collect_by_type(node, target_type, &mut matched);
        }
        Self::new(matched)
    }

    pub fn find_where<F>(&self, predicate: F) -> Self
    where
        F: Fn(&AstNode) -> bool + Copy,
    {
        let mut matched = Vec::new();
        for node in &self.nodes {
            collect_by_predicate(node, predicate, &mut matched);
        }
        Self::new(matched)
    }

    pub fn filter<F>(&self, predicate: F) -> Self
    where
        F: Fn(&AstNode) -> bool,
    {
        let filtered: Vec<AstNode> = self
            .nodes
            .iter()
            .filter(|n| predicate(n))
            .cloned()
            .collect();
        Self::new(filtered)
    }

    pub fn map<F>(&self, transform: F) -> Self
    where
        F: Fn(&AstNode) -> AstNode,
    {
        let mapped: Vec<AstNode> = self.nodes.iter().map(transform).collect();
        Self::new(mapped)
    }

    pub fn for_each<F>(&self, mut callback: F)
    where
        F: FnMut(&AstNode),
    {
        for node in &self.nodes {
            callback(node);
        }
    }

    pub fn replace_with<F>(&mut self, transform: F)
    where
        F: Fn(AstNode) -> AstNode,
    {
        self.nodes = self.nodes.drain(..).map(transform).collect();
    }

    pub fn remove(&mut self) {
        self.nodes.clear();
    }
}

fn collect_by_type(node: &AstNode, target_type: &str, acc: &mut Vec<AstNode>) {
    if node.node_type == target_type {
        acc.push(node.clone());
    }
    for child in &node.children {
        collect_by_type(child, target_type, acc);
    }
}

fn collect_by_predicate<F>(node: &AstNode, predicate: F, acc: &mut Vec<AstNode>)
where
    F: Fn(&AstNode) -> bool + Copy,
{
    if predicate(node) {
        acc.push(node.clone());
    }
    for child in &node.children {
        collect_by_predicate(child, predicate, acc);
    }
}
