{"command":"create","summary":"Create src/match_node.rs","file_text":"use crate::collection::AstNode;
use serde_json::Value;

pub fn match_node(node: &AstNode, pattern: &Value) -> bool {
    match pattern {
        Value::Object(map) => {
            for (key, expected_val) in map {
                if key == "type" {
                    if let Value::String(s) = expected_val {
                        if node.node_type != *s {
                            return false;
                        }
                    } else {
                        return false;
                    }
                    continue;
                }

                match node.attributes.get(key) {
                    Some(actual_val) => {
                        if !match_json_value(actual_val, expected_val) {
                            return false;
                        }
                    }
                    None => return false,
                }
            }
            true
        }
        _ => false,
    }
}

pub fn match_json_value(actual: &Value, expected: &Value) -> bool {
    match (actual, expected) {
        (Value::Object(act_map), Value::Object(exp_map)) => {
            for (k, v) in exp_map {
                match act_map.get(k) {
                    Some(act_v) => {
                        if !match_json_value(act_v, v) {
                            return false;
                        }
                    }
                    None => return false,
                }
            }
            true
        }
        (Value::Array(act_arr), Value::Array(exp_arr)) => {
            if act_arr.len() < exp_arr.len() {
                return false;
            }
            for (act_item, exp_item) in act_arr.iter().zip(exp_arr.iter()) {
                if !match_json_value(act_item, exp_item) {
                    return false;
                }
            }
            true
        }
        _ => actual == expected,
    }
}
