{"command":"create","file_text":"use crate::collection::AstNode;
use std::collections::HashMap;

pub struct Template;

impl Template {
    pub fn statement(source: &str, replacements: &HashMap<String, AstNode>) -> AstNode {
        let mut node = AstNode::new("ExpressionStatement");
        node.attributes.insert(
            "raw".to_string(),
            serde_json::Value::String(source.to_string()),
        );

        for (k, v) in replacements {
            node.attributes.insert(
                format!("placeholder_{}", k),
                serde_json::Value::String(v.node_type.clone()),
            );
            node.children.push(v.clone());
        }

        node
    }

    pub fn expression(source: &str) -> AstNode {
        let mut node = AstNode::new("Expression");
        node.attributes.insert(
            "raw".to_string(),
            serde_json::Value::String(source.to_string()),
        );
        node
    }

    pub fn statements(source: &str) -> Vec<AstNode> {
        source
            .split(';')
            .map(|s| s.trim())
            .filter(|s| !s.is_empty())
            .map(|stmt| {
                let mut node = AstNode::new("ExpressionStatement");
                node.attributes.insert(
                    "raw".to_string(),
                    serde_json::Value::String(stmt.to_string()),
                );
                node
            })
            .collect()
    }
}
