#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum ParserType {
    Babel,
    Babylon,
    Flow,
    Ts,
    Tsx,
}

impl ParserType {
    pub fn from_str(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "babel" => Some(ParserType::Babel),
            "babylon" => Some(ParserType::Babylon),
            "flow" => Some(ParserType::Flow),
            "ts" => Some(ParserType::Ts),
            "tsx" => Some(ParserType::Tsx),
            _ => None,
        }
    }

    pub fn as_str(&self) -> &'static str {
        match self {
            ParserType::Babel => "babel",
            ParserType::Babylon => "babylon",
            ParserType::Flow => "flow",
            ParserType::Ts => "ts",
            ParserType::Tsx => "tsx",
        }
    }
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct ParserOptions {
    pub parser_type: Option<ParserType>,
    pub custom_config: Option<serde_json::Value>,
}

impl ParserOptions {
    pub fn new(parser_type: ParserType) -> Self {
        Self {
            parser_type: Some(parser_type),
            custom_config: None,
        }
    }
}
