{"summary":"Create src/utils.rs","file_text":"use std::collections::HashSet;
use std::hash::Hash;
use std::sync::Once;

pub fn intersection<T: Eq + Hash + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let set_b: HashSet<&T> = b.iter().collect();
    a.iter()
        .filter(|item| set_b.contains(item))
        .cloned()
        .collect()
}

pub fn union<T: Eq + Hash + Clone>(a: &[T], b: &[T]) -> Vec<T> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();

    for item in a.iter().chain(b.iter()) {
        if seen.insert(item.clone()) {
            result.push(item.clone());
        }
    }

    result
}

pub struct OnceCell {
    once: Once,
}

impl OnceCell {
    pub const fn new() -> Self {
        Self {
            once: Once::new(),
        }
    }

    pub fn call_once<F>(&self, f: F)
    where
        F: FnOnce(),
    {
        self.once.call_once(f);
    }
}
