{"summary":"Create src/main.rs","command":"create","file_text":"use jscodeshift::args::{parse, ParseOutcome};
use jscodeshift::runner::run;
use std::io::{self, BufRead, Write};

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();

    let outcome = match parse(&args) {
        Ok(o) => o,
        Err(e) => {
            if e.exit_code != 0 {
                let _ = io::stderr().write_all(e.message.as_bytes());
            } else {
                let _ = io::stdout().write_all(e.message.as_bytes());
            }
            std::process::exit(e.exit_code);
        }
    };

    let mut options = match outcome {
        ParseOutcome::Help(text) => {
            let _ = io::stdout().write_all(text.as_bytes());
            std::process::exit(0);
        }
        ParseOutcome::Version(text) => {
            let _ = io::stdout().write_all(text.as_bytes());
            std::process::exit(0);
        }
        ParseOutcome::Success(opts) => opts,
    };

    if options.stdin {
        let stdin = io::stdin();
        for line in stdin.lock().lines() {
            if let Ok(l) = line {
                let trimmed = l.trim().to_string();
                if !trimmed.is_empty() {
                    options.positional_arguments.push(trimmed);
                }
            }
        }
    }

    match run(&options) {
        Ok(code) => std::process::exit(code),
        Err(err) => {
            eprintln!("Error: {}", err);
            std::process::exit(1);
        }
    }
}
